param([ValidateSet('Inspect','LegacyRuntime','Backup','Migrate','Grant','Provision','VerifyRuntime','Test','Inventory','Regression','Purchasing','Final','Certify')][string]$Action,[ValidateSet('uat','expenses','credits','returns','cheques','receipts','sales','classification','purchasing','inventory','regression')][string]$Scope='sales',[ValidateSet('01','02','03','04','05','06','07','08')][string]$RunId='01',[switch]$ExecuteReviewedPlan)
$ErrorActionPreference='Stop'

$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'));$private=Join-Path $root 'server/.local/p27c';$profiles=Join-Path $root 'server/.local/p21a'
if(-not(Test-Path -LiteralPath $private)){New-Item -ItemType Directory -Path $private|Out-Null;$acl=Get-Acl -LiteralPath $private;$acl.SetAccessRuleProtection($true,$false);foreach($sid in @([Security.Principal.WindowsIdentity]::GetCurrent().User,[Security.Principal.SecurityIdentifier]::new('S-1-5-18'))){$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($sid,'FullControl','ContainerInherit,ObjectInherit','None','Allow'))};Set-Acl -LiteralPath $private -AclObject $acl}
if((Get-Item -LiteralPath $private).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Private directory cannot be a link'}
$connection=Get-Content -LiteralPath (Join-Path $profiles 'owner.connection.json') -Raw|ConvertFrom-Json
if($connection.host -ne '127.0.0.1' -or $connection.port -ne 3309 -or $connection.database -and $connection.database -ne 'upms'){throw 'Recovered endpoint mismatch'}
$names=@('DB_HOST','DB_PORT','DB_NAME','DB_CONFIRM_NAME','DB_USER','DB_PASSWORD','DB_ALLOW_MARIADB_COMPATIBILITY','IDENTITY_DB_PURPOSE','NODE_ENV','UPMS_P27C_PLAN','UPMS_P27C_SCHEMA','UPMS_P27C_USER','UPMS_P27C_PASSWORD','UPMS_P27C_MIGRATOR','UPMS_P27C_MIGRATOR_PASSWORD','UPMS_P27C_RUN','UPMS_P27C_SCOPE','UPMS_P27C_STAGE','UPMS_P25A_STAGE','UPMS_P25A_SCOPE','UPMS_P25_RUN','UPMS_P25_OWNER_USER','UPMS_P25_OWNER_PASSWORD','UPMS_P24_STAGE','UPMS_P24_RUN','UPMS_P24_OWNER_USER','UPMS_P24_OWNER_PASSWORD','UPMS_P27C_OWNER_USER','UPMS_P27C_OWNER_PASSWORD','UPMS_P23_STAGE','UPMS_P23_RUN','UPMS_P23_OWNER_USER','UPMS_P23_OWNER_PASSWORD','UPMS_P22_PREMIGRATED','UPMS_TEST_OWNER_USER','UPMS_TEST_OWNER_PASSWORD','UPMS_P22_OWNER_USER','UPMS_P22_OWNER_PASSWORD')
$saved=@{};foreach($name in $names){$saved[$name]=[Environment]::GetEnvironmentVariable($name,'Process')};$buffers=[Collections.Generic.List[IntPtr]]::new()
function Secret($secure){$buffer=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure);$buffers.Add($buffer);return [Runtime.InteropServices.Marshal]::PtrToStringBSTR($buffer)}
function Generate($name,$path){if(Test-Path -LiteralPath $path){throw 'Existing private run profile; preserve without reuse'};$bytes=[byte[]]::new(36);[Security.Cryptography.RandomNumberGenerator]::Fill($bytes);$secret=ConvertTo-SecureString ([Convert]::ToBase64String($bytes)) -AsPlainText -Force;[Array]::Clear($bytes,0,$bytes.Length);$cred=[PSCredential]::new($name,$secret);$cred|Export-Clixml -LiteralPath $path -NoClobber;return $cred}
Push-Location -LiteralPath $root
try{
  $credentialProfile=if($Action -eq 'Migrate'){'migrator'}elseif($Action -eq 'LegacyRuntime'){'runtime'}else{'owner'};$credential=Import-Clixml -LiteralPath (Join-Path $profiles "$credentialProfile.credential.clixml")
  $env:DB_HOST='127.0.0.1';$env:DB_PORT='3309';$env:DB_NAME='upms';$env:DB_CONFIRM_NAME='upms';$env:DB_USER=$credential.UserName;$env:DB_PASSWORD=Secret $credential.Password;$env:DB_ALLOW_MARIADB_COMPATIBILITY='true';$env:IDENTITY_DB_PURPOSE='operator';$env:NODE_ENV='development'
  $env:UPMS_P27C_PLAN=if($ExecuteReviewedPlan){'reviewed-p27c-additive'}else{''};$env:UPMS_P27C_RUN=$RunId;$env:UPMS_P27C_SCOPE=$Scope;$env:UPMS_P27C_SCHEMA="upms_test_p27c_$($Scope)_20261023_$RunId";$env:UPMS_P27C_USER="upms_runtime_test_p27c$(if($Scope -eq 'receipts'){'e'}elseif($Scope -eq 'cheques'){'q'}elseif($Scope -eq 'returns'){'t'}elseif($Scope -eq 'credits'){'f'}elseif($Scope -eq 'expenses'){'x'}else{$Scope.Substring(0,1)})$RunId";$env:UPMS_P27C_MIGRATOR="upms_migrator_test_p27c$(if($Scope -eq 'receipts'){'e'}elseif($Scope -eq 'cheques'){'q'}elseif($Scope -eq 'returns'){'t'}elseif($Scope -eq 'credits'){'f'}elseif($Scope -eq 'expenses'){'x'}else{$Scope.Substring(0,1)})$RunId"
  $runtimePath=Join-Path $private "$Scope-$RunId-runtime.credential.clixml";$migratorPath=Join-Path $private "$Scope-$RunId-migrator.credential.clixml";$node=Join-Path $root 'tmp/w05/runtime/node_modules/node/bin/node.exe'
  if($Action -eq 'Provision'){if(-not $ExecuteReviewedPlan){throw 'Reviewed plan execution required'};$runtime=Generate $env:UPMS_P27C_USER $runtimePath;$migration=Generate $env:UPMS_P27C_MIGRATOR $migratorPath;$env:UPMS_P27C_PASSWORD=Secret $runtime.Password;$env:UPMS_P27C_MIGRATOR_PASSWORD=Secret $migration.Password}
  if($Action -eq 'VerifyRuntime'){$runtime=Import-Clixml -LiteralPath (Join-Path $profiles 'runtime.credential.clixml');$env:UPMS_P27C_SCHEMA='upms';$env:UPMS_P27C_USER=$runtime.UserName;$env:UPMS_P27C_PASSWORD=Secret $runtime.Password}
  if($Action -in @('Test','Inventory','Regression','Purchasing')){
    if(($Action -eq 'Test' -and $Scope -notin @('sales','classification','receipts','cheques','returns','credits','expenses')) -or ($Action -eq 'Inventory' -and $Scope -ne 'inventory') -or ($Action -eq 'Regression' -and $Scope -ne 'regression') -or ($Action -eq 'Purchasing' -and $Scope -ne 'purchasing')){throw 'Suite/scope mismatch'}
    $started=Join-Path $private "$Scope-$RunId-started.json";if(Test-Path -LiteralPath $started){throw 'Acceptance already started; preserve populated schema'}
    $runtime=Import-Clixml -LiteralPath $runtimePath;$owner=Import-Clixml -LiteralPath (Join-Path $profiles 'owner.credential.clixml');$env:DB_NAME=$env:UPMS_P27C_SCHEMA;$env:DB_CONFIRM_NAME=$env:DB_NAME;$env:DB_USER=$runtime.UserName;$env:DB_PASSWORD=Secret $runtime.Password;$env:IDENTITY_DB_PURPOSE='runtime';$env:UPMS_P27C_STAGE='true';$env:UPMS_P25A_STAGE='true';$env:UPMS_P25A_SCOPE=$Scope;$env:UPMS_P25_RUN=$RunId;$env:UPMS_P25_OWNER_USER=$owner.UserName;$env:UPMS_P25_OWNER_PASSWORD=Secret $owner.Password;$env:UPMS_P24_STAGE='true';$env:UPMS_P24_RUN=$RunId;$env:UPMS_P24_OWNER_USER=$owner.UserName;$env:UPMS_P24_OWNER_PASSWORD=Secret $owner.Password;$env:UPMS_P27C_OWNER_USER=$owner.UserName;$env:UPMS_P27C_OWNER_PASSWORD=Secret $owner.Password;$env:UPMS_P23_OWNER_USER=$owner.UserName;$env:UPMS_P23_OWNER_PASSWORD=$env:UPMS_P27C_OWNER_PASSWORD;$env:UPMS_TEST_OWNER_USER=$owner.UserName;$env:UPMS_TEST_OWNER_PASSWORD=$env:UPMS_P27C_OWNER_PASSWORD;$env:UPMS_P22_OWNER_USER=$owner.UserName;$env:UPMS_P22_OWNER_PASSWORD=$env:UPMS_P27C_OWNER_PASSWORD;$env:UPMS_P22_PREMIGRATED='true';$env:UPMS_P23_STAGE='true';$env:UPMS_P23_RUN=$RunId
    & $node server/tools/database-preflight.mjs;if($LASTEXITCODE -ne 0){throw 'Preflight refused before fixtures'}
    @{schema=$env:DB_NAME;startedUtc=[DateTime]::UtcNow.ToString('o')}|ConvertTo-Json|Set-Content -LiteralPath $started;New-Item -ItemType Directory -Path tmp/w06/p27c,tmp/w06/p27c/legacy-inventory,tmp/w06/p27c/legacy-purchasing -Force|Out-Null
    if($Action -eq 'Regression'){foreach($suite in @('identity','business')){& $node --test "server/tests/mysql/$suite.integration.js" *> "tmp/w06/p27c/$suite-$RunId.log";if($LASTEXITCODE -ne 0){throw "$suite regression failed; preserve schema"};Get-Content "tmp/w06/p27c/$suite-$RunId.log" -Tail 9;if($suite -eq 'identity'){$text=Get-Content "tmp/w06/p27c/$suite-$RunId.log" -Raw;if($text -notmatch 'pass 17' -or $text -notmatch 'tests 17'){throw 'Identity assertion count changed'};@{passed=$true;checks=17;topLevel=$true;database=$env:DB_NAME}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $private "identity-$RunId.json")}}}
    else{$suite=if($Action -eq 'Inventory'){'inventory'}elseif($Action -eq 'Purchasing'){'purchases'}elseif($Scope -eq 'receipts'){'receipts'}elseif($Scope -eq 'cheques'){'cheques'}elseif($Scope -eq 'returns'){'returns'}elseif($Scope -eq 'credits'){'credits'}elseif($Scope -eq 'expenses'){'expenses'}else{'sales'};& $node --test "server/tests/mysql/$suite.integration.js" *> "tmp/w06/p27c/$Scope-$RunId.log";Get-Content "tmp/w06/p27c/$Scope-$RunId.log" -Tail 16;if($LASTEXITCODE -ne 0){throw "$suite acceptance failed; preserve schema"}}
  }else{& $node server/tools/expense-operations.mjs $Action.ToLowerInvariant();if($LASTEXITCODE -ne 0){throw 'P2.7C operation stopped; retain all evidence and state'}}
}finally{Pop-Location;foreach($buffer in $buffers){[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($buffer)};foreach($name in $names){[Environment]::SetEnvironmentVariable($name,$saved[$name],'Process')}}
